-- CCN Mock Exam Day 13 (4 Nov 2026): 200 questions, 10 sections of 20, full-curriculum council-style revision
-- (mock 1 of 3): curated bank questions plus new hard ICU questions, with 20 ICU management questions.
-- Adds the questions as hidden exam-only copies (not shown in the practice app) and creates the exam for the
-- Critical Care section (09:00–23:55 Nigeria time, 200 minutes, 1 attempt, answers shown after each question).
-- Times can be changed on the admin page. If the exam already exists, only its questions are updated.
-- Safe to run more than once.
set lock_timeout = '5s';
begin;
create temporary table dnew (n int primary key, topic text, q text, opts jsonb, ans_idx int, exp text, category text) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + d.n, d.topic, 'CCN Mock Exam — Day 13 (4 Nov 2026)', d.q, d.opts, d.ans_idx, d.exp, d.category, '📝', false
from dnew d
where not exists (select 1 from public.questions x where x.source = 'CCN Mock Exam — Day 13 (4 Nov 2026)' and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from dnew d join public.questions x on x.source = 'CCN Mock Exam — Day 13 (4 Nov 2026)' and x.q = d.q), instructions = 'Day 13. Full-curriculum council-style mock (200 questions across all areas of critical care nursing, including ICU management). Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 200 minutes.', starts_at = timestamptz '2026-11-04 09:00:00+01', ends_at = timestamptz '2026-11-04 23:55:00+01', duration_minutes = 200 where title = 'CCN Mock Exam — Day 13 (200 Questions)';
                               show_answers, show_score, max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'CCN Mock Exam — Day 13 (200 Questions)', 'Day 13. Full-curriculum council-style mock (200 questions across all areas of critical care nursing, including ICU management). Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 200 minutes.', timestamptz '2026-11-04 09:00:00+01', timestamptz '2026-11-04 23:55:00+01', 200, (select array_agg(x.id order by d.n) from dnew d join public.questions x on x.source = 'CCN Mock Exam — Day 13 (4 Nov 2026)' and x.q = d.q),
       true, true, 100, true, true, 1, 'relaxed', 'ccn'
where not exists (select 1 from public.exam_exams where title = 'CCN Mock Exam — Day 13 (200 Questions)');
select title, specialty, cardinality(question_ids) as questions_in_exam, starts_at, ends_at from public.exam_exams where title = 'CCN Mock Exam — Day 13 (200 Questions)';
commit;
