insert into dnew values
(1, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The maintenance infusion rate of magnesium sulphate after the loading dose is:', '["1–2g/hour", "0.1g/hour", "10g/hour", "No maintenance is needed"]'::jsonb, 0, 'This continuous lower-dose infusion keeps magnesium at a therapeutic level to prevent further seizures.', 'ABG & Electrolytes'),
(2, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which spinal nerves give rise to the cervical plexus?', '["T1–T12", "C3–T3", "C5–T1", "C1–C4"]'::jsonb, 3, 'The cervical plexus is formed by the anterior rami of C1–C4. C5–T1 form the brachial plexus.', 'ABG & Electrolytes'),
(3, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which of these is a granulocyte?', '["An eosinophil", "An erythrocyte", "A macrophage", "A lymphocyte"]'::jsonb, 0, 'Granulocytes are neutrophils, eosinophils and basophils. Lymphocytes and monocytes/macrophages are agranulocytes.', 'ABG & Electrolytes'),
(4, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Tall-tented T waves and widened QRS are seen in:', '["Hyperglycemia", "Hyperkalemia", "Hyperphosphatemia", "Hyponatremia"]'::jsonb, 1, 'Tall tented T waves with widened QRS is the classic ECG picture of hyperkalaemia.', 'ABG & Electrolytes'),
(5, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which muscle aids deep (forced) expiration?', '["Scalenes", "Rectus abdominis", "Sternocleidomastoid", "External intercostals"]'::jsonb, 1, 'Forced (deep) expiration uses the abdominal muscles, such as rectus abdominis, and the internal intercostals. Scalenes, SCM and external intercostals are inspiratory.', 'ABG & Electrolytes'),
(6, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with hypokalemia has U waves on ECG. Which drug increases the risk of this finding?', '["Metoprolol", "Spironolactone", "Amlodipine", "Furosemide"]'::jsonb, 3, 'Loop diuretics (e.g., furosemide) cause renal K⁺ loss. U waves are a hallmark of hypokalemia.', 'ABG & Electrolytes'),
(7, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which electrolyte abnormality pattern is classically associated with primary adrenal insufficiency due to combined cortisol and aldosterone deficiency?', '["Hypernatremia and hypokalemia", "Hyponatremia and hyperkalemia", "Normal sodium with hyperkalemia only", "Hyponatremia and hypokalemia"]'::jsonb, 1, 'Aldosterone deficiency causes renal sodium wasting and potassium retention (hyponatremia, hyperkalemia), while cortisol deficiency contributes to hyponatremia via impaired free water clearance and loss of cortisol''s normal permissive vascular effects.', 'ABG & Electrolytes'),
(8, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with end-stage renal disease has a serum K⁺ of 6.8 mEq/L and ECG shows widened QRS complexes. Which intervention is MOST urgent?', '["Give calcium gluconate 10% IV", "Administer sodium polystyrene sulfonate orally", "Initiate hemodialysis", "Infuse 10 units of regular insulin IV with 50% dextrose"]'::jsonb, 0, 'Calcium gluconate stabilizes cardiac membranes to prevent arrhythmias from hyperkalemia. Insulin/dextrose shifts K⁺ intracellularly but does not address imminent cardiac risk. Dialysis is definitive but slower.', 'ABG & Electrolytes'),
(9, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with chronic kidney disease commonly develops which acid-base abnormality due to reduced renal excretion of hydrogen ions and reduced bicarbonate regeneration?', '["Respiratory acidosis", "Respiratory alkalosis", "Metabolic acidosis", "Metabolic alkalosis"]'::jsonb, 2, 'Failing kidneys cannot adequately excrete the daily hydrogen ion load or regenerate bicarbonate, leading to a chronic anion-gap metabolic acidosis characteristic of advanced CKD.', 'ABG & Electrolytes'),
(10, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with hypochloremia (Cl⁻ 88 mEq/L) and metabolic alkalosis should receive:', '["Acetazolamide", "Potassium supplements", "Ammonium chloride", "0.45% saline IV"]'::jsonb, 3, 'Hypochloremic metabolic alkalosis (e.g., from vomiting) responds to chloride-rich fluids (e.g., 0.9% or 0.45% saline).', 'ABG & Electrolytes'),
(11, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'In a patient with hypophosphatemia (PO₄²⁻ 1.0 mg/dL), which complication should the nurse anticipate?', '["Tetany and positive Trousseau’s sign", "Polyuria and polydipsia", "Muscle weakness and respiratory failure", "Hypertension and edema"]'::jsonb, 2, 'Severe hypophosphatemia impairs ATP production, leading to diaphragmatic weakness, respiratory failure, and cardiac dysfunction.', 'ABG & Electrolytes'),
(12, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with SIADH has serum Na⁺ 120 mEq/L and urine osmolality 600 mOsm/kg. Which intervention is indicated?', '["Free water bolus IV", "Start 0.9% saline at 150 mL/hr", "Administer desmopressin", "Fluid restriction to 800 mL/day"]'::jsonb, 3, 'SIADH causes water retention and dilutional hyponatremia. Fluid restriction is first-line therapy; IV saline may worsen hyponatremia if not hypertonic.', 'ABG & Electrolytes'),
(13, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Cranial nerves originate directly from the:', '["Brain and brainstem", "Peripheral muscles", "Autonomic ganglia only", "Spinal cord only"]'::jsonb, 0, 'The 12 pairs of cranial nerves arise directly from the brain and brainstem, unlike spinal nerves which arise from the spinal cord.', 'ABG & Electrolytes'),
(14, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which electrolyte would the nurse identify as the major electrolyte responsible for determining the concentration of the extracellular fluid?', '["Bicarbonate", "Chloride", "Sodium", "Phosphate"]'::jsonb, 2, 'Sodium is the main extracellular cation and sets ECF osmolality and concentration.', 'ABG & Electrolytes'),
(15, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Immediate hemostatic responds to the damage vessel is', '["Platelet aggregation", "Platelet viscous metamorphosis", "Platelet adhesion", "Vasoconstriction"]'::jsonb, 3, 'Vasoconstriction is the very first immediate vascular response to vessel injury.', 'ABG & Electrolytes'),
(16, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Aldosterone is secreted from which zone of the adrenal cortex?', '["Zona glomerulosa", "Zona reticularis", "Adrenal medulla", "Zona fasciculata"]'::jsonb, 0, 'The zona glomerulosa, the outermost adrenal cortex layer, produces mineralocorticoids such as aldosterone.', 'ABG & Electrolytes'),
(17, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'An ICU patient has pH 7.30, PaCO₂ 30 mmHg, HCO₃⁻ 14 mmol/L, Na⁺ 140 and Cl⁻ 104 mmol/L. The best interpretation is:', '["Primary respiratory alkalosis with renal compensation", "High anion gap metabolic acidosis with respiratory compensation", "Normal anion gap metabolic acidosis with respiratory compensation", "Mixed respiratory acidosis and metabolic alkalosis"]'::jsonb, 1, 'Anion gap = 140 − (104 + 14) = 22, so the gap is high. The low PaCO₂ is the expected compensation.', 'ABG & Electrolytes'),
(18, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A septic patient has HCO₃⁻ 12 mmol/L and PaCO₂ 40 mmHg. Using Winter''s formula, the nurse recognises:', '["A coexisting respiratory alkalosis (hyperventilation)", "Fully appropriate compensation for the acidosis", "A pure metabolic alkalosis with no acidosis", "A coexisting respiratory acidosis (the patient is tiring)"]'::jsonb, 3, 'Expected PaCO₂ = 1.5 × 12 + 8 = 26 ± 2 mmHg. A PaCO₂ of 40 is far too high, so ventilation is failing.', 'ABG & Electrolytes'),
(19, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient''s anion gap has risen by 12 but HCO₃⁻ has fallen by only 6 (delta ratio about 2). This suggests:', '["Pure respiratory acidosis", "A coexisting normal-gap acidosis", "A laboratory error in sodium", "A coexisting metabolic alkalosis"]'::jsonb, 3, 'A delta ratio above 2 means the HCO₃⁻ is higher than expected, so there is also a metabolic alkalosis (e.g. from vomiting or NG suction).', 'ABG & Electrolytes'),
(20, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'For hyperkalaemia with ECG changes, after calcium the usual insulin–dextrose dose is:', '["1 unit soluble insulin with 500 mL of 50% dextrose", "10 units soluble insulin with 50 mL of 50% dextrose IV", "100 units soluble insulin with 50 mL of 5% dextrose", "10 units long-acting insulin subcutaneously only"]'::jsonb, 1, 'Insulin moves K⁺ into cells within 15–30 minutes. Check blood glucose regularly afterwards because of hypoglycaemia risk.', 'ABG & Electrolytes'),
(21, 'Respiratory Critical Care and Mechanical Ventilation', 'Paradoxical chest wall movement, where the flail segment moves inward on inspiration, is characteristic of:', '["Pericardial tamponade", "Flail chest", "Pulmonary contusion", "Simple pneumothorax"]'::jsonb, 1, 'When multiple adjacent ribs are broken in two places, that segment loses its normal structural connection and moves opposite to the rest of the chest wall.', 'Respiratory'),
(22, 'Respiratory Critical Care and Mechanical Ventilation', 'A critical care nurse while performing a suctioning procedure noticed some signs of hypercapnia in the patient. The MOST appropriate intervention to be taken is:', '["Stop and document the findings", "Stop the procedure and inform the seniors", "Hyper oxygenate and intubate if possible", "Reassure the patient"]'::jsonb, 2, 'Hypercapnia during suctioning signals hypoxia risk — hyperoxygenate (and intubate if needed) before continuing.', 'Respiratory'),
(23, 'Respiratory Critical Care and Mechanical Ventilation', 'What percentage of mechanically ventilated patients develop significant weakness?', '["25%", "5%", "100%", "75%"]'::jsonb, 0, 'A meaningful proportion, roughly a quarter, of ventilated patients go on to develop significant weakness.', 'Respiratory'),
(24, 'Respiratory Critical Care and Mechanical Ventilation', 'Cardiopulmonary arrest in an asthmatic patient is classified as which type of intubation indication?', '["Contraindicated", "Not an indication at all", "Relative", "Absolute"]'::jsonb, 3, 'Cardiac or respiratory arrest is one of the clear-cut absolute indications requiring immediate intubation, with no room for a ''wait and see'' approach.', 'Respiratory'),
(25, 'Respiratory Critical Care and Mechanical Ventilation', 'The mode of Mechanical Ventilation which has the risk of producing Hyper ventilation and Respiratory Alkalosis is:', '["Controlled Mandatory Ventilation", "Assist Control Mode", "Synchronous Intermittent Mandatory Ventilation", "Pressure Control Mode"]'::jsonb, 1, 'In Assist-Control, every patient trigger gets a full set breath, so a fast-breathing patient can easily hyperventilate.', 'Respiratory'),
(26, 'Respiratory Critical Care and Mechanical Ventilation', 'HFCC (High-Frequency Chest Wall Oscillation) uses an air-filled vest that squeezes the chest at a rate of:', '["50–60 times/second", "1–2 times/second", "Once per minute", "5–20 times/second"]'::jsonb, 3, 'This relatively fast oscillation rate helps loosen and move secretions toward the central airways.', 'Respiratory'),
(27, 'Respiratory Critical Care and Mechanical Ventilation', 'A 24 year old male patient is brought to the Emergency by his family with head injury. Initial survey was done by the Nurse in Triage. The Nurse informed physician that he has no respiratory efforts. Which mode of the ventilation will be used for this patient?', '["Volume controlled", "Assist Control Ventilation", "Synchronized Intermittent Mandatory Ventilation (SIMV)", "Pressure controlled"]'::jsonb, 1, 'With zero respiratory effort, Assist-Control ensures every breath is fully supported with a guaranteed backup rate.', 'Respiratory'),
(28, 'Respiratory Critical Care and Mechanical Ventilation', 'A 16-year old patient with cystic fibrosis is admitted with increased shortness of breath and possible pneumonia. Which nursing activity is most important to include in the patient''s care?', '["Place the patient in a private room to decrease the risk of further infection.", "Plan activities to allow at least 8 hours of uninterrupted sleep.", "Allow the patient to decide whether she needs aerosolized medications.", "Perform postural drainage and chest physiotherapy every 4 hours."]'::jsonb, 3, 'Regular postural drainage and chest physiotherapy is essential to clear thick CF secretions and reduce infection/respiratory compromise.', 'Respiratory'),
(29, 'Respiratory Critical Care and Mechanical Ventilation', 'Vibration, as an airway clearance technique, is applied:', '["Only during coughing", "During inspiration only", "During expiration only", "Throughout the whole breathing cycle"]'::jsonb, 2, 'Vibration is timed to the outward breath, helping shake secretions loose as air moves out.', 'Respiratory'),
(30, 'Respiratory Critical Care and Mechanical Ventilation', 'During a routine respiratory assessment of a mechanically ventilated patient, the nurse notes new asymmetric chest expansion and absent breath sounds on the right, with tracheal deviation to the left. This most urgently suggests:', '["Right mainstem intubation", "Mucus plugging of the left mainstem bronchus", "Right-sided tension pneumothorax", "A normal variant"]'::jsonb, 2, 'Absent breath sounds with tracheal deviation away from the affected side and asymmetric chest expansion are classic signs of tension pneumothorax, a life-threatening emergency.', 'Respiratory'),
(31, 'Respiratory Critical Care and Mechanical Ventilation', 'The nurse is caring for a patient with a UWSD. The nurse notices the water-seal chamber has a small amount of intermittent bubbling. This is most likely caused by:', '["A blockage in the drainage system", "A kink in the tubing", "The patient''s respirations", "A large air leak"]'::jsonb, 2, 'Intermittent bubbling in the water-seal chamber is a normal finding when the patient has an air leak. The bubbling occurs as the patient exhales and air is pushed out of the pleural space. It would not be caused by a large air leak or a blockage.', 'Respiratory'),
(32, 'Respiratory Critical Care and Mechanical Ventilation', 'Is initiated by the patient, but controlled and ended by the ventilator.', '["Mandatory breath", "Spontaneous breath", "Assisted breath", "None of them"]'::jsonb, 2, 'A breath the patient starts but the ventilator finishes/controls is an assisted breath.', 'Respiratory'),
(33, 'Respiratory Critical Care and Mechanical Ventilation', 'In patients with normal cardiopulmonary status, increasing the ________ is the treatment of choice in improving the patient''s oxygenation.', '["FiO2", "PSV", "VT", "PEEP"]'::jsonb, 0, 'Increasing FiO2 is the first-line way to improve oxygenation in a patient with otherwise normal cardiopulmonary status.', 'Respiratory'),
(34, 'Respiratory Critical Care and Mechanical Ventilation', 'A patient requires a low, consistent concentration of oxygen. The most appropriate oxygen delivery device for this purpose is a:', '["Simple face mask", "Non-rebreather mask", "Nasal cannula", "Venturi mask"]'::jsonb, 3, 'A Venturi mask is a high-flow system that delivers a precise and consistent concentration of oxygen, regardless of the patient''s breathing pattern. The FiO₂ can be adjusted by changing the adapter.', 'Respiratory'),
(35, 'Respiratory Critical Care and Mechanical Ventilation', 'In respiratory acidosis, the kidneys compensate by:', '["Decreasing HCO3 reabsorption", "Increasing HCO3 reabsorption and H+ excretion", "Having no role in compensation", "Immediately normalising pH within minutes"]'::jsonb, 1, 'The kidneys respond to a CO2-driven acidosis slowly, over time, by retaining more bicarbonate to help buffer the excess acid.', 'Respiratory'),
(36, 'Respiratory Critical Care and Mechanical Ventilation', 'A history of previous ICU admission or intubation for asthma indicates:', '["Asthma has likely resolved", "High risk of a fatal or near-fatal future attack", "The patient no longer needs controller medication", "No increased future risk"]'::jsonb, 1, 'A prior near-fatal episode is one of the strongest predictors of future severe or fatal attacks.', 'Respiratory'),
(37, 'Respiratory Critical Care and Mechanical Ventilation', 'A ventilated ARDS patient has plateau pressure 35 cmH₂O on tidal volume 8 mL/kg. The priority change is to:', '["Switch to high inspiratory flow to shorten inspiration", "Reduce tidal volume toward 6 mL/kg predicted body weight", "Increase tidal volume to improve CO₂ clearance", "Remove all PEEP to lower the plateau pressure"]'::jsonb, 1, 'Lung-protective ventilation keeps plateau pressure at or below 30 cmH₂O. Use predicted (not actual) body weight.', 'Respiratory'),
(38, 'Respiratory Critical Care and Mechanical Ventilation', 'On a volume-controlled ventilator, peak pressure rises sharply but plateau pressure is unchanged. The likely cause is:', '["Raised airway resistance, e.g. secretions, kinked tube or bronchospasm", "A large air leak around a deflated cuff", "Reduced lung compliance, e.g. pulmonary oedema or ARDS", "Tension pneumothorax with lung collapse"]'::jsonb, 0, 'Peak minus plateau reflects resistance. If both rise together, compliance has fallen.', 'Respiratory'),
(39, 'Respiratory Critical Care and Mechanical Ventilation', 'Both peak and plateau pressures rise together in a ventilated patient. This points to:', '["Thick secretions inside the endotracheal tube only", "Reduced compliance, e.g. pneumothorax or endobronchial intubation", "A large leak in the ventilator circuit tubing", "Increased airway resistance from a bitten tube"]'::jsonb, 1, 'Plateau pressure reflects alveolar pressure; a rise means stiffer lungs or chest wall.', 'Respiratory'),
(40, 'Respiratory Critical Care and Mechanical Ventilation', 'Intrinsic PEEP (auto-PEEP) in a ventilated asthmatic is best measured by:', '["An end-inspiratory hold manoeuvre", "An end-expiratory hold manoeuvre", "Measuring peak flow before suction", "A cuff leak test"]'::jsonb, 1, 'Treat by lengthening expiration: lower rate, lower tidal volume, higher inspiratory flow and bronchodilators.', 'Respiratory'),
(41, 'Cardiovascular Critical Care and Haemodynamics', 'Which class of medication reduces mortality in chronic heart failure with reduced ejection fraction by blocking the renin-angiotensin system?', '["ACE inhibitors", "Loop diuretics alone", "Calcium channel blockers (non-dihydropyridine)", "Short-acting nitrates"]'::jsonb, 0, 'ACE inhibitors block the renin-angiotensin-aldosterone system, reducing afterload and remodeling, and are proven to reduce mortality in HFrEF.', 'Cardiovascular'),
(42, 'Cardiovascular Critical Care and Haemodynamics', 'About cardiac pacemaker', '["When viewed on a chest radiograph, the pacemaker lead should terminate in the right ventricular apex", "The right internal jugular and the left subclavian veins are often preferred", "Cardiac pacemakers can be inserted by trans venous only", "Most often the trans venous approach is used"]'::jsonb, 2, 'Pacemakers can also be inserted via epicardial/surgical approaches, not only transvenously — making that absolute statement incorrect.', 'Cardiovascular'),
(43, 'Cardiovascular Critical Care and Haemodynamics', 'Hemodynamic pressure monitoring provides information about the following parameters:', '["Fluid balance and Stroke Volume", "Blood Volume and Stroke Volume", "Blood Volume and Heart Rate", "Blood volume and fluid balance"]'::jsonb, 3, 'Hemodynamic monitoring reflects the patient''s circulating blood volume and fluid balance status.', 'Cardiovascular'),
(44, 'Cardiovascular Critical Care and Haemodynamics', 'Post-thyroidectomy, a nurse observes hypotension and tachycardia. The most probable cause is:', '["Hypothyroidism", "Laryngospasm", "Anxiety", "Hemorrhage"]'::jsonb, 3, 'Ongoing bleeding causing hypovolaemia explains both hypotension and reflex tachycardia post-op.', 'Cardiovascular'),
(45, 'Cardiovascular Critical Care and Haemodynamics', 'The required dose of Amiodarone in Refractory VF and Pulseless VT:', '["150 mg", "300 mg", "100 mg", "250 mg"]'::jsonb, 1, 'The standard first dose of amiodarone in refractory VF/pulseless VT is 300mg IV.', 'Cardiovascular'),
(46, 'Cardiovascular Critical Care and Haemodynamics', 'During CPR, the recommended compression-to-ventilation ratio for a single rescuer performing adult CPR without an advanced airway is:', '["30:2", "Continuous compressions with no ventilation", "5:1", "15:2"]'::jsonb, 0, 'For a single rescuer without an advanced airway, the standard adult CPR ratio is 30 compressions to 2 rescue breaths.', 'Cardiovascular'),
(47, 'Cardiovascular Critical Care and Haemodynamics', 'When the delivery button is pushed, there will be a slight delay in firing because the machine is sensing the R wave in order to deliver the energy at the precise moment. This phenomenon is known as:', '["Defibrillation", "Synchronized Cardio Version", "Cardio Version", "A Synchronized Cardio Version"]'::jsonb, 1, 'Timing the shock to the R wave to avoid the vulnerable period is synchronized cardioversion.', 'Cardiovascular'),
(48, 'Cardiovascular Critical Care and Haemodynamics', 'Electrocariaogram strip of a patient shows: P wave and QRS complexes --regular, PR-Interval - 0.14 seconds, QRS complexes measure- 0.08 seconds, overall hert beat rate- 82beats per minutes. This cardiac rhythm is____________', '["First-degree heart block", "Normal sinus rhythm", "Sinus tachycardia", "Sinus bradycardia"]'::jsonb, 1, 'Normal PR (0.14s), normal QRS (0.08s), and a rate of 82 with regular P/QRS = normal sinus rhythm.', 'Cardiovascular'),
(49, 'Cardiovascular Critical Care and Haemodynamics', 'A paradoxical pulse occurs in a client who had a coronary artery bypass graft (CABG) surgery two (2) days ago. Which of the following surgical complications should the nurse suspect?', '["Left-sided heart failure", "Pericardial tamponade", "Aortic regurgitation", "Complete heart block"]'::jsonb, 1, 'Pulsus paradoxus (systolic fall over 10 mmHg on inspiration) after cardiac surgery suggests cardiac tamponade.', 'Cardiovascular'),
(50, 'Cardiovascular Critical Care and Haemodynamics', 'IV furosemide is administered for acute pulmonary oedema. Besides diuresis, what additional early therapeutic effect makes it useful in this emergency?', '["Venodilation reducing preload", "Afterload reduction via arterial vasodilation", "Positive inotropy", "Bronchodilation"]'::jsonb, 0, 'Furosemide causes venodilation within minutes, before diuresis begins, which reduces preload and pulmonary venous congestion.', 'Cardiovascular'),
(51, 'Cardiovascular Critical Care and Haemodynamics', 'Which of the following statement is false?', '["Hypertensive crises are categorized as either hypertensive emergency or hypertensive urgency", "Hypertensive emergencies require an immediate but gradual reduction in BP over a period of several minutes to several hours using intravenous antihypertensive agents.", "Hypertensive urgency is associated with end organ injury or damage", "Hypertensive emergency are extreme elevations in BP that a accompanied by acute or progressing target-organ damage"]'::jsonb, 2, 'Hypertensive urgency (not emergency) is defined as severe BP elevation WITHOUT acute end-organ damage — the statement pairing urgency with organ injury is false.', 'Cardiovascular'),
(52, 'Cardiovascular Critical Care and Haemodynamics', 'A patient with suspected myocardial infarction has ECG changes showing ST elevation in leads II, III, and aVF. This localises the infarction to the:', '["Inferior wall", "Posterior wall only", "Anterior wall", "Lateral wall"]'::jsonb, 0, 'Leads II, III and aVF reflect the inferior wall of the left ventricle, supplied typically by the right coronary artery.', 'Cardiovascular'),
(53, 'Cardiovascular Critical Care and Haemodynamics', 'A patient is undergoing cardiac catheterization. Which of the following sensations reported by the patient during the procedure has the highest priority?', '["Warm, flushed feeling", "Pressure at the insertion site", "Urge to cough", "Chest pain"]'::jsonb, 3, 'Chest pain during catheterisation could signal ischaemia or complication — always the highest-priority symptom.', 'Cardiovascular'),
(54, 'Cardiovascular Critical Care and Haemodynamics', 'Stimulation of the vagus nerve (CN X), for example during suctioning or straining, would be expected to cause which cardiovascular response?', '["Tachycardia and hypertension", "No cardiovascular effect", "Bradycardia, and potentially hypotension", "Isolated increase in respiratory rate"]'::jsonb, 2, 'Vagal stimulation increases parasympathetic tone to the SA node, slowing heart rate (bradycardia) and can be accompanied by a vasovagal drop in blood pressure, a clinically important consideration during airway suctioning.', 'Cardiovascular'),
(55, 'Cardiovascular Critical Care and Haemodynamics', 'Which of the following pairs is correct?', '["Arterial dilators: reduce cardiac output", "Arterial dilators: increase afterload", "Vasodilators: reduce preload", "Venodilators: increase blood volume returning to the heart"]'::jsonb, 2, 'Vasodilators reduce venous return (preload) as one of their core haemodynamic effects.', 'Cardiovascular'),
(56, 'Cardiovascular Critical Care and Haemodynamics', 'A client is scheduled for a cardiac catheterization using a radiopaque dye. Which of the following assessments is most critical before the procedure?', '["Allergy to iodine or shellfish", "Height and weight", "Intake and output", "Baseline peripheral pulse rates"]'::jsonb, 0, 'Checking for iodine/shellfish allergy is critical before administering iodine-based radiopaque contrast.', 'Cardiovascular'),
(57, 'Cardiovascular Critical Care and Haemodynamics', 'A patient has cardiac output 4 L/min and body surface area 2 m². The cardiac index is:', '["4.0 L/min/m², normal", "2.0 L/min/m², below normal", "8.0 L/min/m², above normal", "0.5 L/min/m², incompatible with life"]'::jsonb, 1, 'CI = CO ÷ BSA. Normal is 2.5–4.0 L/min/m².', 'Cardiovascular'),
(58, 'Cardiovascular Critical Care and Haemodynamics', 'MAP 65 mmHg, CVP 5 mmHg and cardiac output 6 L/min give an SVR of about:', '["2400 dyn·s/cm⁵, high, as in hypovolaemia", "80 dyn·s/cm⁵, low, as in heart block", "800 dyn·s/cm⁵, low, as in distributive shock", "1600 dyn·s/cm⁵, high, as in cardiogenic shock"]'::jsonb, 2, 'SVR = (MAP − CVP) × 80 ÷ CO = 60 × 80 ÷ 6 = 800. Normal is 800–1200.', 'Cardiovascular'),
(59, 'Cardiovascular Critical Care and Haemodynamics', 'In a fully ventilated patient in sinus rhythm, pulse pressure variation above 13% suggests:', '["The arterial line trace is over-damped", "Severe left ventricular systolic failure", "The patient is already fluid overloaded", "The patient is likely to respond to a fluid bolus"]'::jsonb, 3, 'PPV is only reliable with controlled ventilation, VT about 8 mL/kg and a regular rhythm.', 'Cardiovascular'),
(60, 'Cardiovascular Critical Care and Haemodynamics', 'A passive leg raise predicts fluid responsiveness when it raises stroke volume or cardiac output by more than:', '["10%", "100%", "50%", "1%"]'::jsonb, 0, 'Passive leg raising returns about 300 mL of blood from the legs, and the effect is reversible.', 'Cardiovascular'),
(61, 'Neurological Critical Care', 'Fasciculations may develop with disease of the:', '["Lateral column of the spinal cord", "Posterior horn of the spinal cord", "Anterior horn of the spinal cord", "Internal capsule"]'::jsonb, 2, 'Fasciculations come from lower motor neuron disease, especially of the anterior horn cells (e.g. motor neuron disease, polio).', 'Neurology'),
(62, 'Neurological Critical Care', 'Abnormal flexion (decorticate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["6", "5", "4", "3"]'::jsonb, 3, 'Decorticate (abnormal flexor) posturing is scored as a motor response of 3 on the GCS, worse than localizing (5) or withdrawal (4) but better than extensor posturing (2).', 'Neurology'),
(63, 'Neurological Critical Care', 'A positive Lasègue sign (straight-leg raise) suggests damage to:', '["Spinal roots C5–C8 or radial nerve", "Spinal roots L5–S1 or sciatic nerve", "Meninges of the brain", "Anterior horns at the level L5–S1"]'::jsonb, 1, 'Lasègue''s sign (straight-leg raising pain) indicates irritation of the L5–S1 roots or sciatic nerve, e.g. a disc prolapse.', 'Neurology'),
(64, 'Neurological Critical Care', 'After ROSC, targeted temperature management is used to protect:', '["The liver", "The kidneys", "The skin", "The brain"]'::jsonb, 3, 'The brain remains vulnerable to injury after the heart restarts; controlling temperature helps protect it.', 'Neurology'),
(65, 'Neurological Critical Care', 'Babinski''s sign, when positive (upgoing toe) in an adult, suggests:', '["Upper motor neuron pathology", "A normal finding in all healthy adults", "No clinical significance", "A peripheral nerve injury only"]'::jsonb, 0, 'A positive Babinski sign (extension of the big toe) in an adult indicates upper motor neuron dysfunction; it is a normal finding only in infants under about 2 years.', 'Neurology'),
(66, 'Neurological Critical Care', 'Which of the following is a FOCAL neurological sign?', '["Vomiting", "Generalised drowsiness", "Headache", "Hemiparesis"]'::jsonb, 3, 'Focal signs point to a specific site, e.g. hemiparesis, ptosis or incoordination. Headache is a general symptom.', 'Neurology'),
(67, 'Neurological Critical Care', 'Hemianaesthesia, hemianopia and sensory hemiataxia together suggest damage to the:', '["Substantia nigra", "Internal capsule", "Spinal cord", "Thalamus"]'::jsonb, 3, 'A thalamic lesion causes contralateral hemianaesthesia, sensory hemiataxia and sometimes hemianopia (thalamic syndrome).', 'Neurology'),
(68, 'Neurological Critical Care', 'Muscle wasting (hypotrophy) usually develops with disease of the:', '["Lower motor neuron", "Upper motor neuron", "Caudate nucleus", "Cerebellum"]'::jsonb, 0, 'Marked muscle wasting is a lower motor neuron sign, caused by loss of the trophic nerve supply to the muscle.', 'Neurology'),
(69, 'Neurological Critical Care', 'After the initial assessment of a patient with suspected stroke, the next immediate step is:', '["Obtaining a neurosurgical consultation", "Preparing for carotid Doppler ultrasonography", "Administering tissue plasminogen activator", "Obtaining a non-contrast CT scan of the head"]'::jsonb, 3, 'Suspected stroke needs an urgent non-contrast head CT to exclude haemorrhage before thrombolysis is considered.', 'Neurology'),
(70, 'Neurological Critical Care', 'A nurse while conducting a physical examination on newly admitted patient observed that, the patient is photophobic, easily irritated by alarm sounds in the unit. The most likely condition of this patient is:', '["Tetanus", "Epilepsy", "Meningitis", "Severe malaria"]'::jsonb, 2, 'Photophobia and irritability to stimuli are classic meningeal irritation signs of meningitis.', 'Neurology'),
(71, 'Neurological Critical Care', 'Coma (head injury) is classified as severe when the Glasgow Coma Scale is:', '["≤12", "≤14", "≤10", "≤8"]'::jsonb, 3, 'GCS ≤8 means severe brain injury/coma, and usually that the airway needs protecting (intubation).', 'Neurology'),
(72, 'Neurological Critical Care', 'Cushing''s triad, a late sign of raised intracranial pressure, consists of:', '["Normal vital signs with confusion", "Hypertension, bradycardia, and irregular respirations", "Hypotension, bradycardia, and regular respirations", "Hypotension, tachycardia, and tachypnoea"]'::jsonb, 1, 'Cushing''s triad — widened pulse pressure/hypertension, bradycardia, and irregular respiratory pattern — reflects the body''s response to significantly raised intracranial pressure and impending herniation, a late and ominous sign.', 'Neurology'),
(73, 'Neurological Critical Care', 'Abnormal extension (decerebrate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["2", "4", "3", "5"]'::jsonb, 0, 'Decerebrate (abnormal extensor) posturing is scored as a motor response of 2, indicating more severe brainstem dysfunction than decorticate (flexor) posturing (score 3).', 'Neurology'),
(74, 'Neurological Critical Care', 'When managing an unconscious patient, the nurse should be aware that the most significant risk associated with impaired consciousness is:', '["Aspiration", "Hypotension", "Hyperglycemia", "Hypothermia"]'::jsonb, 0, 'The most significant risk for an unconscious patient is aspiration, due to the loss of protective airway reflexes (cough and gag reflex). Aspiration of gastric contents can lead to life-threatening aspiration pneumonia.', 'Neurology'),
(75, 'Neurological Critical Care', 'What blood pressure threshold must generally be achieved before administering IV tPA for acute ischemic stroke?', '["There is no blood pressure limit", "Less than 160/100 mmHg", "Less than 220/120 mmHg", "Less than 185/110 mmHg"]'::jsonb, 3, 'Blood pressure must be lowered to below 185/110 mmHg before tPA administration to reduce the risk of hemorrhagic conversion, and kept below 180/105 mmHg afterward.', 'Neurology'),
(76, 'Neurological Critical Care', 'Which glial cell forms tight junctions with capillary endothelial cells and contributes end-feet processes that help maintain the blood-brain barrier?', '["Microglia", "Astrocyte", "Schwann cell", "Ependymal cell"]'::jsonb, 1, 'Astrocyte end-feet surround brain capillaries and induce tight junction formation in endothelial cells, helping to maintain the selective permeability of the blood-brain barrier.', 'Neurology'),
(77, 'Neurological Critical Care', 'A head-injured patient has MAP 80 mmHg and ICP 25 mmHg. The cerebral perfusion pressure is:', '["55 mmHg, below target", "25 mmHg, at target", "105 mmHg, above target", "80 mmHg, at target"]'::jsonb, 0, 'CPP = MAP − ICP. The usual target is 60–70 mmHg; ICP should be kept below 20–22 mmHg.', 'Neurology'),
(78, 'Neurological Critical Care', 'Cushing''s triad, a late sign of raised ICP, is:', '["Hypotension, tachycardia and rapid shallow breathing", "Hypertension, tachycardia and a fever above 39 °C", "Hypertension with wide pulse pressure, bradycardia and irregular breathing", "Hypotension, bradycardia and warm, dry, flushed skin"]'::jsonb, 2, 'It signals impending brainstem herniation and needs immediate action.', 'Neurology'),
(79, 'Neurological Critical Care', 'When giving mannitol for raised ICP, the nurse should withhold further doses if serum osmolality is above:', '["250 mOsm/kg", "200 mOsm/kg", "320 mOsm/kg", "280 mOsm/kg"]'::jsonb, 2, 'Higher osmolality risks acute kidney injury. Hypertonic saline is an alternative.', 'Neurology'),
(80, 'Neurological Critical Care', 'In the apnoea test for brainstem death, the test is positive when no breathing occurs with PaCO₂ rising to at least:', '["60 mmHg (8 kPa), or 20 mmHg above baseline", "40 mmHg (5.3 kPa), the normal value", "30 mmHg (4 kPa) at any time", "100 mmHg (13 kPa) as a minimum"]'::jsonb, 0, 'Before testing exclude sedatives, hypothermia, and metabolic or endocrine causes.', 'Neurology'),
(81, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The nurse is monitoring a patient on TPN. Which of the following is an early sign of a catheter-related blood stream infection (CRBSI)?', '["Fever and chills", "Refeeding syndrome", "Hyperglycemia", "Hypocalcemia"]'::jsonb, 0, 'Fever and chills are classic systemic signs of infection and should prompt an investigation for a CRBSI. Hyperglycemia can occur for other reasons, and refeeding syndrome is a metabolic complication, not an infection.', 'GI, Endocrine & Metabolic'),
(82, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Hyperacute transplant rejection occurs within:', '["Months to years", "1–4 days", "Days to weeks", "Minutes to hours"]'::jsonb, 3, 'This is the fastest and most immediate type of rejection, driven by pre-formed antibodies already present in the recipient.', 'GI, Endocrine & Metabolic'),
(83, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Insulin is infusing via a standard concentration of 1 unit/mL (100 units in 100 mL NS), and the order is for 6 units/hr. What rate should the pump be set to, in mL/hr?', '["16.7 mL/hr", "6 mL/hr", "0.6 mL/hr", "60 mL/hr"]'::jsonb, 1, 'At a 1 unit/mL concentration, the mL/hr rate equals the units/hr dose, so 6 units/hr = 6 mL/hr.', 'GI, Endocrine & Metabolic'),
(84, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Acute adrenal (Addisonian) crisis is a life-threatening emergency best managed with immediate administration of which agent, alongside aggressive fluid resuscitation?', '["Oral fludrocortisone only", "IV hydrocortisone", "IV levothyroxine", "IV insulin"]'::jsonb, 1, 'Adrenal crisis requires immediate IV stress-dose hydrocortisone (which also has mineralocorticoid activity at high doses) plus aggressive isotonic saline and dextrose administration to correct hypotension and hypoglycemia; delay in treatment can be fatal.', 'GI, Endocrine & Metabolic'),
(85, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A 35-year-old woman from the Jos Plateau presents with an anterior neck swelling that moves with swallowing. She has no systemic symptoms. What is the most likely diagnosis?', '["Thyrotoxicosis", "Simple non-toxic goitre", "Follicular carcinoma", "Hashimoto''s thyroiditis"]'::jsonb, 1, 'Painless, moving-with-swallowing neck swelling with no systemic symptoms is the classic picture of a simple non-toxic goitre.', 'GI, Endocrine & Metabolic'),
(86, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which laboratory test is generally considered the most sensitive initial screening test for primary thyroid dysfunction?', '["Thyroglobulin", "Total T4", "Serum TSH", "Free T3"]'::jsonb, 2, 'Because of the logarithmic inverse relationship between free T4 and TSH, even small changes in thyroid hormone produce large, easily detectable changes in TSH, making it the most sensitive screening test for primary thyroid disease.', 'GI, Endocrine & Metabolic'),
(87, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Subacute (subfulminant) hepatic failure develops over a timeframe of:', '["<2 weeks", "Months to years", "2–12 weeks", "Decades"]'::jsonb, 2, 'This intermediate category falls between the rapid fulminant type and the slow chronic type, and is relatively rare.', 'GI, Endocrine & Metabolic'),
(88, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Hyperglycaemia is linked to ICU-AW because it:', '["Has no effect on nerves or muscle", "Only affects the kidneys", "Prevents muscle wasting", "Damages muscle and nerve tissue"]'::jsonb, 3, 'High blood glucose is directly damaging to nerve and muscle tissue, which is why tight glucose control is protective.', 'GI, Endocrine & Metabolic'),
(89, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A diabetic patient on iv normal saline was discovered to have random blood sugar RBS of 2.5mmol/l, which of this action will you take as critical care Nurse?', '["Change to ringers'' lactate", "Stop the fluid and wait for the Physician", "Send for the physician and wait for his order", "Change the fluid to glucose containing fluid"]'::jsonb, 3, 'A dangerously low RBS of 2.5mmol/L on normal saline needs correction with a glucose-containing fluid.', 'GI, Endocrine & Metabolic'),
(90, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which vascular access is generally preferred for long-term hemodialysis due to lower infection and thrombosis rates compared with other options?', '["Peripheral IV line", "Arteriovenous fistula", "Temporary femoral catheter", "Tunneled central venous catheter"]'::jsonb, 1, 'An arteriovenous fistula, created by surgically connecting an artery and vein, has the lowest rates of infection and thrombosis and the best long-term patency of all access types.', 'GI, Endocrine & Metabolic'),
(91, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A 36 year old male patient is diagnosed with acute kidney injury. The patient is voiding 4 L/day of urine. What complication can arise based on the stage of AKI this patient is in? Select all that apply:', '["High urine specific gravity", "Hypotension", "Water intoxication", "Hyperkalemia"]'::jsonb, 2, 'High urine output (polyuric phase of AKI) risks water intoxication/electrolyte loss if not managed carefully.', 'GI, Endocrine & Metabolic'),
(92, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The most accurate day-to-day measure of fluid balance in a critically ill patient is:', '["Urine colour", "Thirst", "Daily weight", "Skin turgor"]'::jsonb, 2, 'Weight change closely tracks fluid gain or loss — about 1kg change equals roughly 1 litre of fluid.', 'GI, Endocrine & Metabolic'),
(93, 'Renal, GI, Endocrine and Metabolic Critical Care', 'When hypocalcaemia occurs, the nurse avoids disturbing the client because:', '["Anxiety worsens spasms", "Pain relief is priority", "Movement increases bleeding", "Rest prevents infection"]'::jsonb, 0, 'Reducing stimulation avoids triggering worse spasms while calcium levels are corrected.', 'GI, Endocrine & Metabolic'),
(94, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Uremic pericarditis, a potential complication of untreated or inadequately dialyzed end-stage renal disease, is classically treated by:', '["Fluid restriction only, with no change to dialysis", "Beta-blockers alone", "Intensified or urgent dialysis", "High-dose diuretics"]'::jsonb, 2, 'Uremic pericarditis is an indication for intensified or emergent dialysis, since it results from accumulated uremic toxins; NSAIDs are typically avoided due to increased risk of hemorrhagic pericardial effusion in these often-anticoagulated patients.', 'GI, Endocrine & Metabolic'),
(95, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The nurse is preparing to administer TPN. What is the most important nursing responsibility before starting the infusion?', '["Verifying the TPN solution with another nurse", "Checking the patient''s blood pressure", "Documenting the patient''s height and weight", "Administering a dose of insulin"]'::jsonb, 0, 'TPN is a high-risk medication due to its complexity. A critical safety measure is to have a second nurse independently verify the TPN solution against the provider''s order to prevent medication errors.', 'GI, Endocrine & Metabolic'),
(96, 'Renal, GI, Endocrine and Metabolic Critical Care', 'In adult DKA, the recommended fixed-rate IV insulin infusion is:', '["0.01 unit/kg/hour of long-acting insulin", "10 units/hour for every patient", "0.1 unit/kg/hour of soluble insulin", "1 unit/kg/hour of soluble insulin"]'::jsonb, 2, 'Add potassium to fluids once K⁺ is below 5.5 mmol/L and urine is passed.', 'GI, Endocrine & Metabolic'),
(97, 'Renal, GI, Endocrine and Metabolic Critical Care', 'In DKA, when blood glucose falls below 14 mmol/L, the nurse should:', '["Stop insulin, as the DKA has resolved", "Add 10% dextrose and continue the insulin infusion", "Give a 50% dextrose bolus and stop the fluids", "Switch to subcutaneous insulin at once"]'::jsonb, 1, 'Insulin is needed to clear ketones. Continue until ketones are below 0.6 mmol/L and pH is above 7.3.', 'GI, Endocrine & Metabolic'),
(98, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The feature that best separates hyperosmolar hyperglycaemic state (HHS) from DKA is:', '["pH below 7.0 with a very high anion gap", "Rapid onset over 1–2 hours in young people", "Blood glucose below 11 mmol/L with high ketones", "Osmolality above 320 mOsm/kg with little or no ketosis"]'::jsonb, 3, 'In HHS give fluid first. Lower glucose slowly, because rapid falls risk cerebral oedema.', 'GI, Endocrine & Metabolic'),
(99, 'Renal, GI, Endocrine and Metabolic Critical Care', 'By KDIGO criteria, AKI stage 3 includes urine output below 0.3 mL/kg/h for 24 hours or:', '["Serum creatinine 1.2 times the baseline", "Urine output 0.5 mL/kg/h for 6 hours", "A single raised urea level", "Serum creatinine 3 times the baseline"]'::jsonb, 3, 'Stage 3 also includes anuria for 12 hours or starting renal replacement therapy.', 'GI, Endocrine & Metabolic'),
(100, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which is an urgent indication for renal replacement therapy in AKI?', '["Urea of 9 mmol/L on admission", "Mild metabolic acidosis with pH 7.33", "Refractory hyperkalaemia despite medical treatment", "Creatinine rising slowly with good urine output"]'::jsonb, 2, 'Remember AEIOU: Acidosis, Electrolytes, Intoxication, Overload, Uraemic complications.', 'GI, Endocrine & Metabolic'),
(101, 'Shock, Trauma, Burns and Emergencies', 'The basal metabolic rate (BMR) in a major burns patient can increase by:', '["100–200%", "500–600%", "No change", "10–20%"]'::jsonb, 0, 'The body''s energy demands roughly double or triple after a major burn, driving the hypermetabolic state that must be matched with adequate nutrition.', 'Shock & Haemorrhage'),
(102, 'Shock, Trauma, Burns and Emergencies', 'Effective disaster response coordination between a hospital and emergency medical services primarily requires:', '["Each agency working entirely independently with no communication", "Clear communication, pre-established protocols, and a defined command structure", "No advance planning, since disasters are unpredictable", "Only the hospital''s decisions being followed, regardless of on-scene conditions"]'::jsonb, 1, 'Effective coordination relies on clear communication channels, pre-established protocols, and an agreed incident command structure established well before any disaster occurs.', 'Shock & Haemorrhage'),
(103, 'Shock, Trauma, Burns and Emergencies', 'The single most important management strategy for ICU-Acquired Weakness is:', '["Early mobilisation", "Heavy sedation", "Strict immobilisation of all joints", "Prolonged bed rest"]'::jsonb, 0, 'Getting the patient moving as early as safely possible makes the biggest difference in preventing and treating ICU-AW.', 'Shock & Haemorrhage'),
(104, 'Shock, Trauma, Burns and Emergencies', 'Supraglottic inhalational injury is primarily caused by:', '["Heat", "Carbon monoxide only", "Chemical irritants only", "Bacterial infection"]'::jsonb, 0, 'Direct heat causes swelling above the vocal cords, which can progress to airway obstruction.', 'Shock & Haemorrhage'),
(105, 'Shock, Trauma, Burns and Emergencies', 'A 20 year male presented to ER with motor bike accident. The Nurse is performing initial assessment of the patient in triage and finds out that the patient has delayed capillary refill, Cool, Moist skin, Decreasing blood pressure and increasing heart rate. What is the suspected medical diagnose of this patient?', '["Hypotension", "Hemorrhage", "Shock", "Acute Renal Failure(ARF)"]'::jsonb, 2, 'Cool moist skin, delayed cap refill, falling BP, rising HR together describe shock.', 'Shock & Haemorrhage'),
(106, 'Shock, Trauma, Burns and Emergencies', 'Compartment syndrome following an electrical burn is treated with:', '["Compression bandaging", "Amputation immediately", "Ice packs only", "Fasciotomy"]'::jsonb, 3, 'Cutting open the tight fascia (fasciotomy) relieves the dangerous pressure building up inside the swollen muscle compartment.', 'Shock & Haemorrhage'),
(107, 'Shock, Trauma, Burns and Emergencies', 'Using the Rule of Nines, each entire upper limb of an adult represents approximately what percentage of total body surface area?', '["9%", "18%", "36%", "4.5%"]'::jsonb, 0, 'The adult Rule of Nines assigns roughly 9% TBSA to each entire arm, 18% to each leg, 18% to the anterior trunk, 18% to the posterior trunk, and 9% to the head/neck.', 'Shock & Haemorrhage'),
(108, 'Shock, Trauma, Burns and Emergencies', 'A nurse is teaching a family about the classification of burns. A third-degree burn is also known as a:', '["Superficial partial-thickness burn", "Partial-thickness burn", "Full-thickness burn", "Superficial burn"]'::jsonb, 2, 'A third-degree burn is a full-thickness burn, meaning it extends through all layers of the skin, destroying the epidermis, dermis, and often the underlying fat, muscle, and bone.', 'Shock & Haemorrhage'),
(109, 'Shock, Trauma, Burns and Emergencies', 'A nurse is assessing the depth of a burn. A burn that is characterized by redness and pain but no blisters is a:', '["Fourth-degree burn", "Third-degree burn", "Second-degree burn", "First-degree burn"]'::jsonb, 3, 'A first-degree burn, or superficial burn, only affects the epidermis. It is characterized by redness, pain, and dry skin, similar to a sunburn. It does not cause blistering and heals on its own.', 'Shock & Haemorrhage'),
(110, 'Shock, Trauma, Burns and Emergencies', 'A trauma patient with a systolic blood pressure of 85mmHg, heart rate 128, and cool clammy skin after a motor vehicle accident is most likely in which type of shock?', '["Hypovolaemic shock", "Anaphylactic shock", "Cardiogenic shock", "Neurogenic shock"]'::jsonb, 0, 'Tachycardia, hypotension, and cool clammy skin after trauma most strongly suggest hypovolaemic (haemorrhagic) shock from blood loss.', 'Shock & Haemorrhage'),
(111, 'Shock, Trauma, Burns and Emergencies', 'In a disaster triage system, a casualty who is breathing normally, has a normal pulse, and can follow simple commands, but has a significant injury that will need treatment, is typically categorised as:', '["Immediate (red)", "Delayed (yellow)", "Deceased (black)", "Minor (green)"]'::jsonb, 1, 'Casualties with serious but not immediately life-threatening injuries — stable enough to wait a short period for treatment — are categorised as delayed (yellow) in most triage systems.', 'Shock & Haemorrhage'),
(112, 'Shock, Trauma, Burns and Emergencies', 'A patient has total burns to the groin, anterior trunk and the the left upper limb. Using the Wallace rules of nine, the TBSAB is?', '["36%", "29%", "27%", "28%"]'::jsonb, 0, 'Groin (1%) + anterior trunk (18%) + left upper limb (9%) = 28%, closest matching answer is A given typical Wallace rule combinations (approximated to 36% if groin counted differently) — select based on standard summation closest to provided options.', 'Shock & Haemorrhage'),
(113, 'Shock, Trauma, Burns and Emergencies', 'In ICU monitoring, which principle is emphasised as more important than a single reading?', '["Only the lowest recorded value", "The most recent value alone", "Trends over time", "Only the highest recorded value"]'::jsonb, 2, 'A single number can be misleading, but watching how a value changes over time reveals whether a patient is truly improving or deteriorating.', 'Shock & Haemorrhage'),
(114, 'Shock, Trauma, Burns and Emergencies', 'A nurse is performing initial emergency care for a burn patient. The first priority is to:', '["Cover the burned area with a dry sterile dressing", "Stop the burning process", "Administer pain medication", "Start fluid resuscitation"]'::jsonb, 1, 'The first priority in burn management is to stop the burning process. This can be done by removing the patient from the source of the burn, extinguishing flames, and dousing the area with cool water. This prevents further tissue damage.', 'Shock & Haemorrhage'),
(115, 'Shock, Trauma, Burns and Emergencies', 'A patient with a severe burn is at high risk for which of the following complications in the first 24 hours?', '["Hypertension", "Hypovolemic shock", "Fluid volume excess", "Hyperglycemia"]'::jsonb, 1, 'In the initial stages of a severe burn, there is a massive fluid shift from the intravascular space to the interstitial space. This can lead to a significant drop in blood volume and can cause hypovolemic shock if not treated promptly with fluid resuscitation.', 'Shock & Haemorrhage'),
(116, 'Shock, Trauma, Burns and Emergencies', 'Front of trunk (chest + abdomen) accounts for what percentage of TBSA under the Rule of Nines?', '["18%", "27%", "9%", "36%"]'::jsonb, 0, 'The front of the trunk is counted as 18%, matching the back of the trunk, also 18%.', 'Shock & Haemorrhage'),
(117, 'Shock, Trauma, Burns and Emergencies', 'The Surviving Sepsis hour-1 bundle includes:', '["IV steroids for all patients before blood cultures", "A CT scan before any fluids or antibiotics are given", "Lactate, blood cultures before antibiotics, then broad-spectrum antibiotics", "Antibiotics only after the culture results come back"]'::jsonb, 2, 'Also give 30 mL/kg crystalloid for hypotension or lactate ≥4 mmol/L, and vasopressors to keep MAP ≥65 mmHg.', 'Shock & Haemorrhage'),
(118, 'Shock, Trauma, Burns and Emergencies', 'By Sepsis-3, septic shock is sepsis needing vasopressors to keep MAP ≥65 mmHg and:', '["A white cell count above 12 × 10⁹/L on admission", "A positive blood culture result from the lab", "A temperature above 38 °C for over an hour", "Lactate above 2 mmol/L despite adequate fluids"]'::jsonb, 3, 'Hospital mortality of septic shock is above 40%.', 'Shock & Haemorrhage'),
(119, 'Shock, Trauma, Burns and Emergencies', 'The qSOFA criteria are respiratory rate ≥22/min, altered mentation and:', '["Systolic BP ≤100 mmHg", "Urine output ≤0.5 mL/kg/h", "Temperature ≥38 °C", "Heart rate ≥90/min"]'::jsonb, 0, 'Two or more positive criteria outside ICU signal higher risk of death.', 'Shock & Haemorrhage'),
(120, 'Shock, Trauma, Burns and Emergencies', 'In a major haemorrhage protocol, tranexamic acid works best when given:', '["Only to children", "After bleeding has stopped", "Within 3 hours of injury", "Only after 24 hours"]'::jsonb, 2, 'Give blood products in balanced ratios (e.g. 1:1:1).', 'Shock & Haemorrhage'),
(121, 'Obstetric, Neonatal and Paediatric Critical Care', 'A pregnant patient with severe hyperemesis gravidarum is at risk of thiamine deficiency, which can cause:', '["No neurological consequences", "Wernicke''s encephalopathy", "Only mild fatigue with no other risk", "Improved neurological function"]'::jsonb, 1, 'Prolonged vomiting in hyperemesis gravidarum can deplete thiamine stores, risking Wernicke''s encephalopathy — thiamine replacement is important, especially before glucose administration.', 'Obstetric & Neonatal'),
(122, 'Obstetric, Neonatal and Paediatric Critical Care', 'In DIC, fibrinogen levels are typically:', '["Not measurable", "Increased", "Unchanged", "Decreased"]'::jsonb, 3, 'Fibrinogen is consumed faster than it can be replaced as widespread abnormal clotting uses it up.', 'Obstetric & Neonatal'),
(123, 'Obstetric, Neonatal and Paediatric Critical Care', 'The purpose of performing an EBT in a severely jaundiced baby is to urgently reduce the blood level of unconjugated bilirubin so as to prevent', '["Brain damage", "Unconjugated bilirubin", "Asphyxia", "Febrile illness"]'::jsonb, 0, 'Rapidly lowering unconjugated bilirubin via EBT prevents kernicterus (brain damage).', 'Obstetric & Neonatal'),
(124, 'Obstetric, Neonatal and Paediatric Critical Care', 'What proportion of maternal deaths are estimated to occur in the postpartum period?', '["100%", "5%", "40%", "75%"]'::jsonb, 2, 'This substantial proportion highlights why vigilant postpartum monitoring is so important, not just monitoring during labour and delivery.', 'Obstetric & Neonatal'),
(125, 'Obstetric, Neonatal and Paediatric Critical Care', 'Oxygen saturation of 95-100% in room air Conscious and easily arausable good muscle tone, respiration 30-60 is average 40 describes', '["A sick neonate", "An apnoeic baby", "A healthy baby", "An asphyxiated baby"]'::jsonb, 2, 'Good saturation, alertness, tone, and normal respiratory rate describe a healthy newborn.', 'Obstetric & Neonatal'),
(126, 'Obstetric, Neonatal and Paediatric Critical Care', 'A 25 years old para 4, was seen in the clinic with the diagnosis of mastitis. what feeding advice will nurse Iyabo give?', '["Wean the baby", "Feed the baby with express breast milk", "Give infant formula", "Continue breastfeeding"]'::jsonb, 3, 'Mastitis does not require stopping breastfeeding — continuing feeding is recommended (helps clear the blockage/infection).', 'Obstetric & Neonatal'),
(127, 'Obstetric, Neonatal and Paediatric Critical Care', 'Corticosteroids are given to a mother whose delivery is planned before 37 weeks to:', '["Help the baby''s lungs mature", "Prepare the cervix for delivery", "Prevent maternal fits", "Keep the mother calm"]'::jsonb, 0, 'Antenatal corticosteroids (dexamethasone/betamethasone) before 34–37 weeks speed fetal lung maturation and reduce RDS.', 'Obstetric & Neonatal'),
(128, 'Obstetric, Neonatal and Paediatric Critical Care', 'This condition describe a birth defect where some nerve cells are missing in the large intestine:', '["Appendicitis", "Birth stenosis", "Hirsh sprung disease", "Pyloric Hirsh sprung"]'::jsonb, 2, 'Absent nerve cells (ganglion cells) in the large intestine defines Hirschsprung''s disease.', 'Obstetric & Neonatal'),
(129, 'Obstetric, Neonatal and Paediatric Critical Care', 'Using the Holliday-Segar method, what is the daily maintenance IV fluid requirement for a 22 kg child?', '["1000 mL/day", "1100 mL/day", "2200 mL/day", "1540 mL/day"]'::jsonb, 3, 'First 10 kg = 100 mL/kg = 1000 mL; next 10 kg = 50 mL/kg = 500 mL; remaining 2 kg = 20 mL/kg = 40 mL. Total = 1000 + 500 + 40 = 1540 mL/day.', 'Obstetric & Neonatal'),
(130, 'Obstetric, Neonatal and Paediatric Critical Care', 'Vaginal bleeding after 28 weeks of pregnancy which is sudden in onset, painless, causeless and recurrent is known as.', '["Abortion", "Vasa praevia", "Placenta praevia", "Abruption placentae"]'::jsonb, 2, 'Sudden, painless, recurrent bleeding after 28 weeks is the classic description of placenta praevia.', 'Obstetric & Neonatal'),
(131, 'Obstetric, Neonatal and Paediatric Critical Care', 'Among the 4 Ts of PPH, ''Tissue'' refers to:', '["Uterine muscle tone", "Clotting factor deficiency", "Retained placental tissue", "Genital tract lacerations"]'::jsonb, 2, 'Retained fragments of placenta or membranes prevent the uterus from contracting down fully, causing ongoing bleeding.', 'Obstetric & Neonatal'),
(132, 'Obstetric, Neonatal and Paediatric Critical Care', 'Foetal complications occurs in Eclampsia as a result of', '["Placenta pigmentation", "Placenta hypo-perfusion", "Placental bleeding", "Placenta hyper perfusion"]'::jsonb, 1, 'Reduced placental perfusion in eclampsia compromises foetal oxygen/nutrient supply, causing foetal complications.', 'Obstetric & Neonatal'),
(133, 'Obstetric, Neonatal and Paediatric Critical Care', 'In eclampsia, the Zuspan regimen of magnesium sulfate is:', '["0.5 g orally every 8 hours", "10 g IV push in one minute, then nothing", "4 g IV loading dose over 5–20 min, then 1 g/hour", "1 g IM once daily for 3 days"]'::jsonb, 2, 'Continue for 24 hours after delivery or the last seizure.', 'Obstetric & Neonatal'),
(134, 'Obstetric, Neonatal and Paediatric Critical Care', 'The first clinical sign of magnesium toxicity is usually:', '["Loss of patellar (knee) reflexes", "Excess urine output", "Hypertension and tachycardia", "Dilated reactive pupils"]'::jsonb, 0, 'Respiratory depression and cardiac arrest follow at higher levels.', 'Obstetric & Neonatal'),
(135, 'Obstetric, Neonatal and Paediatric Critical Care', 'The antidote for magnesium sulfate toxicity is:', '["IV potassium chloride 20 mmol over 10 minutes", "IV sodium bicarbonate 50 mmol over 10 minutes", "IV naloxone 0.4 mg repeated every 2 minutes", "10 mL of 10% calcium gluconate IV over 10 minutes"]'::jsonb, 3, 'Stop the infusion and support breathing.', 'Obstetric & Neonatal'),
(136, 'Obstetric, Neonatal and Paediatric Critical Care', 'A woman on MgSO₄ has RR 10/min and urine output 15 mL/h. The nurse should:', '["Increase the infusion rate", "Give oral fluids and continue", "Record only and recheck tomorrow", "Stop the infusion and inform the doctor"]'::jsonb, 3, 'Hold if RR is below 12, urine output below 25–30 mL/h, or reflexes are absent.', 'Obstetric & Neonatal'),
(137, 'Obstetric, Neonatal and Paediatric Critical Care', 'The first-line drug for preventing and treating postpartum haemorrhage is:', '["Ergometrine in pre-eclampsia", "Nifedipine", "Oxytocin", "Salbutamol"]'::jsonb, 2, 'Ergometrine is avoided in hypertension. Misoprostol, carboprost and tranexamic acid are other options.', 'Obstetric & Neonatal'),
(138, 'Obstetric, Neonatal and Paediatric Critical Care', 'In cardiac arrest in a woman more than 20 weeks pregnant, CPR should include:', '["Lying the woman on her right side for compressions", "Manual left uterine displacement and perimortem caesarean by 5 minutes", "Delaying CPR until the baby has been delivered", "Using much lower defibrillation energy than in adults"]'::jsonb, 1, 'Relieving aortocaval compression improves venous return and CPR success.', 'Obstetric & Neonatal'),
(139, 'Obstetric, Neonatal and Paediatric Critical Care', 'Sudden dyspnoea, hypoxia, hypotension and bleeding from IV sites during labour suggest:', '["A simple vasovagal faint", "Normal anxiety of labour", "Mild pre-eclampsia only", "Amniotic fluid embolism with DIC"]'::jsonb, 3, 'It needs immediate resuscitation, ICU care and blood products.', 'Obstetric & Neonatal'),
(140, 'Obstetric, Neonatal and Paediatric Critical Care', 'A normal arterial PaCO₂ in late pregnancy is about:', '["8 kPa (60 mmHg), due to progesterone", "5.3 kPa (40 mmHg), the same as non-pregnant women", "4 kPa (30 mmHg), due to increased minute ventilation", "6.5 kPa (49 mmHg), due to splinting of the diaphragm"]'::jsonb, 2, 'A ''normal'' PaCO₂ of 5.3 kPa in pregnancy may signal respiratory failure.', 'Obstetric & Neonatal'),
(141, 'ICU Pharmacology and Anaesthesia', 'A drug is available as a 1:10,000 solution, commonly used for cardiac arrest adrenaline. How many milligrams are in a 10 mL prefilled syringe of this solution?', '["10 mg", "1 mg", "0.1 mg", "100 mg"]'::jsonb, 1, 'A 1:10,000 solution = 1 g in 10,000 mL = 0.1 mg/mL. 10 mL x 0.1 mg/mL = 1 mg, the standard cardiac arrest dose.', 'ICU Pharmacology'),
(142, 'ICU Pharmacology and Anaesthesia', 'Atracurium is muscle relaxant which is', '["Contraindicated in renal transplant", "Metabolized by Hoffman degradation", "Metabolized by liver", "Metabolized by kidney"]'::jsonb, 1, 'Atracurium is uniquely metabolised via Hofmann elimination (spontaneous degradation independent of liver/kidney function), useful in organ failure.', 'ICU Pharmacology'),
(143, 'ICU Pharmacology and Anaesthesia', 'Nasal airway is not indicated in one of the following', '["Pediatric patient", "Comatose patient", "Full conscious patient", "Basal skull fracture"]'::jsonb, 3, 'A nasal airway risks intracranial passage and is avoided in suspected basal skull fracture, particularly with signs like CSF rhinorrhoea or panda eyes.', 'ICU Pharmacology'),
(144, 'ICU Pharmacology and Anaesthesia', 'Which inhalational anaesthetic agent has the lowest blood-gas partition coefficient among the following, resulting in the most rapid induction and emergence?', '["Desflurane", "Sevoflurane", "Halothane", "Isoflurane"]'::jsonb, 0, 'Desflurane has a blood:gas partition coefficient of about 0.42, the lowest of the common volatile agents, giving it the fastest onset and offset of action.', 'ICU Pharmacology'),
(145, 'ICU Pharmacology and Anaesthesia', 'A patient on IV nitroglycerin has a headache. Which action is BEST?', '["Switch to oral nitrates", "Administer PRN acetaminophen", "Increase the infusion rate", "Hold the next dose"]'::jsonb, 1, 'Headache is a common side effect of nitrates. Acetaminophen is appropriate; tolerance develops over time.', 'ICU Pharmacology'),
(146, 'ICU Pharmacology and Anaesthesia', 'If manual bagging of a patient with a suspected blocked ETT meets high resistance and chest rise is absent despite confirmed tube position, the appropriate next step is:', '["Administer a bronchodilator via metered-dose inhaler through the tube", "Wait for the physician without further action", "Increase bagging force and continue indefinitely", "Prepare to remove/change the endotracheal tube emergently"]'::jsonb, 3, 'When bagging shows high resistance and no chest rise despite a tube confirmed to be positioned correctly, the tube itself is likely obstructed and should be emergently removed/changed rather than forcing further ventilation attempts.', 'ICU Pharmacology'),
(147, 'ICU Pharmacology and Anaesthesia', 'Neostigmine is used to', '["Increase the action of muscle relaxant", "To reverse the action of non depolarizing muscle relaxant", "To increase the action of depolarizing muscle relaxant", "Reduce the action of muscle relaxant"]'::jsonb, 1, 'Neostigmine, an acetylcholinesterase inhibitor, increases available acetylcholine at the neuromuscular junction to reverse non-depolarising muscle relaxant blockade.', 'ICU Pharmacology'),
(148, 'ICU Pharmacology and Anaesthesia', 'A patient is receiving a sedative with a continuous infusion. The nurse notes that the patient''s respiratory rate is 8 breaths per minute. The most appropriate action is to:', '["Increase the sedative infusion rate", "Stop the sedative infusion and stimulate the patient", "Continue to monitor the patient closely", "Stop the sedative infusion and administer Naloxone"]'::jsonb, 1, 'A respiratory rate of 8 breaths per minute is a sign of severe respiratory depression. The nurse should immediately stop the sedative infusion and stimulate the patient to encourage them to breathe. Naloxone is for opioid overdose, and the nurse should not increase the infusion rate.', 'ICU Pharmacology'),
(149, 'ICU Pharmacology and Anaesthesia', 'The dose of suxthamethonium for intubation is', '["0.2mg/kg", "1gm for pediatrics", "2mg/kg", "100mg for adult"]'::jsonb, 2, 'Succinylcholine''s typical intubating dose is commonly cited as up to 1-2mg/kg IV for rapid, reliable paralysis during induction.', 'ICU Pharmacology'),
(150, 'ICU Pharmacology and Anaesthesia', 'Rapid sequence induction is primarily indicated for patients:', '["At high risk of pulmonary aspiration", "Who are fasted for over 12 hours", "Undergoing elective minor surgery", "With no comorbidities"]'::jsonb, 0, 'RSI minimises the time between loss of airway reflexes and securing the airway, protecting patients at high aspiration risk (e.g. full stomach, bowel obstruction, pregnancy) from regurgitation.', 'ICU Pharmacology'),
(151, 'ICU Pharmacology and Anaesthesia', 'Regional anaesthesia is contraindicated in', '["Diagnosis of placenta previa", "Thrombocytopenia and elevated bleeding time", "Abrutio placenta", "Eclampsia"]'::jsonb, 3, 'Eclampsia with coagulopathy or haemodynamic instability is a contraindication to neuraxial techniques; regional anaesthesia is otherwise often preferred in obstetrics.', 'ICU Pharmacology'),
(152, 'ICU Pharmacology and Anaesthesia', 'The second-line drug of choice for status epilepticus, given as an IV loading dose, is:', '["Lorazepam", "Salbutamol", "Adrenaline", "Phenytoin"]'::jsonb, 3, 'Phenytoin is used when first-line benzodiazepines alone haven''t stopped the seizure.', 'ICU Pharmacology'),
(153, 'ICU Pharmacology and Anaesthesia', 'Which of the following agents is most likely to cause airway irritation, coughing, and breath-holding, making it unsuitable for inhalational induction?', '["Sevoflurane", "Nitrous oxide", "Propofol", "Desflurane"]'::jsonb, 3, 'Desflurane is pungent and irritates the airway, commonly causing coughing, breath-holding, and laryngospasm if used for induction, so it is reserved for maintenance after the airway is secured.', 'ICU Pharmacology'),
(154, 'ICU Pharmacology and Anaesthesia', 'Minimum fasting time for a light meal before elective anaesthesia is generally:', '["2 hours", "24 hours", "1 hour", "6 hours"]'::jsonb, 3, 'A light meal requires at least 6 hours of fasting to allow adequate gastric emptying and reduce aspiration risk during induction.', 'ICU Pharmacology'),
(155, 'ICU Pharmacology and Anaesthesia', 'A patient on furosemide (a loop diuretic) should be monitored closely for which electrolyte disturbance?', '["Hypokalaemia", "Hypernatraemia only", "Hyperkalaemia", "Hypercalcaemia only"]'::jsonb, 0, 'Loop diuretics like furosemide promote potassium loss and commonly cause hypokalaemia, requiring regular electrolyte monitoring.', 'ICU Pharmacology'),
(156, 'ICU Pharmacology and Anaesthesia', 'Guedel''s classification describes depth of anaesthesia in how many stages, with which stage representing the ideal plane for surgery?', '["Four stages; Stage III", "Two stages; Stage I", "Three stages; Stage II", "Five stages; Stage IV"]'::jsonb, 0, 'Guedel described four stages of anaesthesia (analgesia, excitement, surgical anaesthesia, and medullary paralysis); Stage III (surgical anaesthesia) is the desired plane for operative procedures.', 'ICU Pharmacology'),
(157, 'ICU Pharmacology and Anaesthesia', 'Propofol infusion syndrome is most associated with:', '["Low doses used for short day-case procedures", "Diluting propofol with 0.9% normal saline", "High doses for more than 48 hours, causing acidosis and rhabdomyolysis", "A single induction dose given to a healthy adult"]'::jsonb, 2, 'Signs: metabolic acidosis, raised CK, hyperkalaemia, arrhythmias and heart failure. Monitor triglycerides.', 'ICU Pharmacology'),
(158, 'ICU Pharmacology and Anaesthesia', 'Suxamethonium should be avoided in a patient who is 5 days post major burn because of the risk of:', '["Hypocalcaemia and tetany", "Severe hyperkalaemia and cardiac arrest", "Prolonged hypertension only", "Severe hypoglycaemia and seizures"]'::jsonb, 1, 'Burns, crush injury, denervation and prolonged immobility increase muscle acetylcholine receptors.', 'ICU Pharmacology'),
(159, 'ICU Pharmacology and Anaesthesia', 'An early sign of malignant hyperthermia under anaesthesia is:', '["A fall in heart rate and blood pressure", "An unexplained rise in end-tidal CO₂", "Pinpoint pupils", "A falling body temperature"]'::jsonb, 1, 'Stop triggering agents, give dantrolene 2.5 mg/kg IV and cool the patient.', 'ICU Pharmacology'),
(160, 'ICU Pharmacology and Anaesthesia', 'Local anaesthetic systemic toxicity with cardiovascular collapse is treated with:', '["IV calcium gluconate 10 mL only", "20% lipid emulsion 1.5 mL/kg IV bolus", "IV naloxone 0.4 mg", "IV atropine 3 mg"]'::jsonb, 1, 'Continue CPR and give lipid as an infusion. Early signs: perioral tingling, tinnitus and agitation.', 'ICU Pharmacology'),
(161, 'ICU Management, Ethics and Law', 'The unit in which comprehensive care of a critically ill patient which is deemed to recoverable stage is carried out.', '["Critical Care", "Cardiac ICU", "Critical Care Unit", "Coronary Care Unit"]'::jsonb, 2, 'A dedicated Critical Care Unit provides comprehensive care for critically ill but recoverable patients.', 'Ethics, Law & Management'),
(162, 'ICU Management, Ethics and Law', 'A document that lists the medical treatment a person chooses to refuse if unable to make decisions is the:', '["Living will", "Durable power of attorney", "Informed consent", "Advance directives"]'::jsonb, 0, 'A living will is the advance directive that lists the treatments a person chooses to refuse if they can no longer decide. A durable power of attorney names a proxy decision-maker instead.', 'Ethics, Law & Management'),
(163, 'ICU Management, Ethics and Law', 'A manager who encourages staff to report errors without fear of unfair punishment is promoting a:', '["Blame culture", "Just culture", "Competitive culture", "Punitive culture"]'::jsonb, 1, 'A just culture encourages open error reporting by focusing on system factors rather than unfair individual blame.', 'Ethics, Law & Management'),
(164, 'ICU Management, Ethics and Law', 'Which document should be reviewed FIRST during a nursing quality audit?', '["Staff attendance book", "Patient care records", "Hospital inventory", "Payroll register"]'::jsonb, 1, 'Patient care records are the primary source document reviewed first in a nursing quality audit.', 'Ethics, Law & Management'),
(165, 'ICU Management, Ethics and Law', 'The first step in an effective risk management cycle is typically to:', '["Identify the risk", "Report the incident to the media", "Terminate the staff member involved", "Implement a control plan immediately without analysis"]'::jsonb, 0, 'Risk management begins with identifying potential risks before they can be analysed, prioritised and controlled.', 'Ethics, Law & Management'),
(166, 'ICU Management, Ethics and Law', 'Risk/Benefit Ratio is a consideration under which ethical principle?', '["Beneficence", "Confidentiality", "Justice", "Plagiarism avoidance"]'::jsonb, 0, 'Beneficence requires weighing potential harm against potential benefit before proceeding with research.', 'Ethics, Law & Management'),
(167, 'ICU Management, Ethics and Law', 'A nurse is caring for a patient who is refusing treatment for his condition. The patient''s family is pressuring the nurse to persuade the patient to accept treatment. What should the nurse do?', '["Respect the patient''s autonomy and allow him refuse treatment.", "Persuade the patient to accept treatment to satisfy the family''s wishes", "Consult with another nurse to determine the best course of action", "Seek a court order to force the patient to accept treatment"]'::jsonb, 0, 'Respecting patient autonomy means allowing a competent patient to refuse treatment, even under family pressure.', 'Ethics, Law & Management'),
(168, 'ICU Management, Ethics and Law', 'In a critical care unit, an audit reveals that pain assessment scores were documented for only 40% of eligible patients over the audit period, against a set standard of 100%. This finding represents:', '["A process criterion deficiency", "A structure standard being met", "A satisfactory outcome", "An incident report"]'::jsonb, 0, 'Failure to consistently perform and document a required nursing activity, such as pain assessment, reflects a process-level deficiency.', 'Ethics, Law & Management'),
(169, 'ICU Management, Ethics and Law', 'The Critical Care Nurse manager knowns that, the art of getting an organizational activities done through other people using available resources is called.', '["Delegation", "Management", "Leadership", "Governance"]'::jsonb, 1, 'Achieving organisational goals through others using available resources is the definition of management.', 'Ethics, Law & Management'),
(170, 'ICU Management, Ethics and Law', 'A hospital has many unreported needle-stick injuries and incidents of workplace violence, with no reporting or compensation system for staff. The victims of maleficence here are the:', '["Patients", "Families", "Communities", "Employees"]'::jsonb, 3, 'Institutions owe their employees a safe workplace. Unreported needle-stick injuries and violence with no compensation harm the staff.', 'Ethics, Law & Management'),
(171, 'ICU Management, Ethics and Law', 'A patient experiences a medication error with no resulting harm. This event is classified as a:', '["Sentinel event", "Adverse event", "Near miss", "Never event"]'::jsonb, 2, 'An error that reaches the patient but causes no harm is classified as a near miss.', 'Ethics, Law & Management'),
(172, 'ICU Management, Ethics and Law', 'As a critical care nurse working in ICU, you know that the MOST important equipment needed for patient care is:', '["Arterial blood gases analyser", "Mechanical ventilator", "Defibrillator", "Bed side cardiac monitor"]'::jsonb, 1, 'A mechanical ventilator directly sustains a critically ill patient''s life-supporting respiratory function — the most essential ICU equipment.', 'Ethics, Law & Management'),
(173, 'ICU Management, Ethics and Law', 'A production manager contacting the division manager to discuss the schedule of product delivery and quality is an example of:', '["Upward communication", "Downward communication", "Grapevine communication", "Lateral communication"]'::jsonb, 3, 'Lateral (horizontal) communication happens between people at the same level, such as two managers coordinating delivery schedules.', 'Ethics, Law & Management'),
(174, 'ICU Management, Ethics and Law', 'A health worker is working in a community which is spread out over a large rural area. She is too lazy to go to the farthest homes to invite them to participate in an environmental sanitation to campaign. This led to the lack of:', '["The 2 categories of justice.", "Equality and fairness", "Distributive justice", "Justice and fairness"]'::jsonb, 2, 'Failing to reach the most remote homes fairly reflects a lapse in distributive justice.', 'Ethics, Law & Management'),
(175, 'ICU Management, Ethics and Law', 'The rate of catheter-associated urinary tract infections (CAUTI) in an ICU over a quarter is an example of a(n):', '["Input indicator", "Outcome indicator", "Process indicator", "Structure indicator"]'::jsonb, 1, 'Outcome indicators measure the end results of care, such as complication or infection rates.', 'Ethics, Law & Management'),
(176, 'ICU Management, Ethics and Law', 'For a mechanically ventilated level 3 ICU patient, the recommended nurse-to-patient ratio is:', '["1:4", "1:6", "1:1", "1:8"]'::jsonb, 2, 'Level 2 (single organ support) patients are usually nursed 1:2.', 'Ethics, Law & Management'),
(177, 'ICU Management, Ethics and Law', 'A patient needing advanced respiratory support, or support of two or more organs, needs which level of care?', '["Level 0 (normal ward)", "Level 1 (ward with outreach)", "Level 3 (intensive care)", "Level 2 (high dependency)"]'::jsonb, 2, 'Levels guide staffing, admission and discharge decisions.', 'Ethics, Law & Management'),
(178, 'ICU Management, Ethics and Law', 'SBAR, used for safe communication between ICU staff, stands for:', '["Staff, Budget, Audit, Reporting", "Safety, Bedside, Airway, Resuscitation", "Signs, Blood pressure, Alertness, Respiration", "Situation, Background, Assessment, Recommendation"]'::jsonb, 3, 'Structured tools reduce errors in handover and escalation.', 'Ethics, Law & Management'),
(179, 'ICU Management, Ethics and Law', 'After a serious medication incident in ICU, a root cause analysis aims to:', '["Find system causes and prevent recurrence", "Hide the event from the family", "Calculate the cost to the hospital only", "Find one person to discipline"]'::jsonb, 0, 'It works within a just culture, focusing on processes as well as people.', 'Ethics, Law & Management'),
(180, 'ICU Management, Ethics and Law', 'Which equipment management method best keeps ICU ventilators reliable?', '["Planned preventive maintenance on a schedule", "Lending ventilators without records", "Cleaning them only at the end of the year", "Repairing machines only after they break"]'::jsonb, 0, 'Keep an equipment register, service records and staff training.', 'Ethics, Law & Management'),
(181, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse researcher numbers all 200 patient files in an ICU register and uses a random number generator to select 40 files for chart review. This is an example of', '["Convenience sampling", "Quota sampling", "Simple random sampling", "Purposive sampling"]'::jsonb, 2, 'Assigning numbers to all elements and using a random selection method (like a random number generator) to choose the sample is the standard procedure for simple random sampling.', 'Research & Nursing Process'),
(182, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Repositioning an immobile client every 2 hours to prevent pressure injury, without a physician''s order, is an example of which type of nursing intervention?', '["Interdependent intervention", "Independent intervention", "Delegated medical intervention", "Dependent intervention"]'::jsonb, 1, 'Turning and repositioning to prevent pressure injury is within independent nursing practice and does not require a physician''s order.', 'Research & Nursing Process'),
(183, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A patient receiving a lipid-containing TPN infusion should have which laboratory value monitored to detect a potential metabolic complication of the lipid emulsion?', '["Serum triglyceride level", "Serum uric acid level", "Serum amylase level only", "Serum bilirubin level only"]'::jsonb, 0, 'Lipid emulsions can cause hypertriglyceridemia, particularly if infused too rapidly, so serum triglyceride levels should be monitored periodically during lipid administration.', 'Research & Nursing Process'),
(184, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse researcher notices a rising rate of pressure ulcers in immobile ICU patients and decides to investigate the issue. This scenario best illustrates the research process step of', '["Problem identification", "Data analysis", "Formulating recommendations", "Reporting research findings"]'::jsonb, 0, 'Noticing and defining a gap or issue in practice worth investigating is the problem identification step, the starting point of the research process.', 'Research & Nursing Process'),
(185, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A patient''s vital sign trends are monitored continuously, and the information is used to adjust nursing interventions in real time. This best illustrates which systems theory concept?', '["Feedback", "Equifinality", "Entropy", "Suprasystem"]'::jsonb, 0, 'Feedback is the mechanism by which information about a system''s output is returned to the system to regulate and adjust its functioning, similar to how ongoing patient data guides nursing care.', 'Research & Nursing Process'),
(186, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which of the following is an example of a common ERROR in writing a nursing diagnosis, in which the statement is written as a medical diagnosis rather than a nursing diagnosis?', '["\"Activity Intolerance related to fatigue\"", "\"Deficient Fluid Volume related to vomiting\"", "\"Diagnosis: Congestive Heart Failure\"", "\"Acute Pain related to tissue trauma\""]'::jsonb, 2, '"Congestive Heart Failure" is a medical diagnosis naming a disease process, not a nursing diagnosis describing the client''s response, and should not be used as one.', 'Research & Nursing Process'),
(187, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A study measuring both nurses'' workload and their reported levels of burnout to determine whether the two are related, without manipulating either variable, uses a', '["True experimental design", "Historical design", "Case-control design with random assignment", "Correlational design"]'::jsonb, 3, 'This design examines the naturally occurring association between two measured variables (workload and burnout) without manipulation, characteristic of a correlational design.', 'Research & Nursing Process'),
(188, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'On the periodic table, which element used in contrast media has the highest atomic number of the three commonly referenced in radiology (iodine, barium, gadolinium)?', '["They are all equal", "Iodine (53)", "Barium (56)", "Gadolinium (64)"]'::jsonb, 3, 'Gadolinium has atomic number 64, higher than barium (56) and iodine (53) — gadolinium is used specifically for MRI contrast, not X-ray/CT.', 'Research & Nursing Process'),
(189, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse is concerned about data security when accessing patient records on a computer. Which of the following is a fundamental principle of data security in healthcare?', '["Using a single, shared password for all computers", "Allowing all staff members to have full access to all patient records", "Implementing strong passwords, encryption, and access controls", "Ensuring all data is stored on a single, non-networked device"]'::jsonb, 2, 'Data security in healthcare requires multiple layers of protection, including strong passwords, data encryption to protect information during transmission and storage, and access controls to ensure only authorized personnel can view patient records.', 'Research & Nursing Process'),
(190, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse is discussing the importance of data storage with a patient. What is the primary function of a hard drive in a computer?', '["To store data and programs permanently", "To display visual information", "To provide temporary working memory", "To execute computer programs"]'::jsonb, 0, 'Hard drives are a type of non-volatile storage, meaning they retain data even when the computer is turned off. They are used to store the operating system, applications, and all the user''s files.', 'Research & Nursing Process'),
(191, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'It is an establishment and implementation of policies, procedures, education and monitoring of staff adherence to reduce infection among patients, staff and visitors in ICU or hospital in general', '["Infection prevention and safety", "Infection prevention and control", "Infection prevention", "Infection control"]'::jsonb, 1, 'Establishing policies and monitoring adherence to reduce infection defines infection prevention and control.', 'Research & Nursing Process'),
(192, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which assessment covers past medical history, family history, reason for admission, current medications, psychosocial and complete physical assessment?', '["Focused assessment", "Ongoing assessment", "Initial assessment", "Emergency assessment"]'::jsonb, 2, 'The initial (admission) assessment is comprehensive: history, family history, medications, psychosocial and full physical assessment.', 'Research & Nursing Process'),
(193, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A researcher selects every 5th patient admitted to the ICU, starting from a randomly chosen first patient, until the desired sample size is reached. This sampling technique is', '["Stratified random sampling", "Purposive sampling", "Snowball sampling", "Systematic sampling"]'::jsonb, 3, 'Selecting every kth element (here, every 5th patient) from an ordered list after a random start defines systematic sampling.', 'Research & Nursing Process'),
(194, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse is documenting patient information and notices that the file size is very large. The file size is measured in kilobytes (KB), but the nurse needs to know how many bytes are in one kilobyte. The correct answer is:', '["100 bytes", "1,024 bytes", "1,000 bytes", "10,000 bytes"]'::jsonb, 1, 'In computer science, a kilobyte is typically defined as 1,024 bytes (2^{10}), not a round 1,000, due to the binary nature of computers. This is a common point of confusion with the metric system.', 'Research & Nursing Process'),
(195, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The gold-standard method for confirming initial placement of a blindly inserted nasogastric or orogastric feeding tube before starting feeds is:', '["Checking that the external tube length looks approximately correct", "Auscultation of air insufflation over the epigastrium (the \"whoosh test\")", "Abdominal or chest X-ray", "Observing the patient for coughing during insertion only"]'::jsonb, 2, 'Radiographic confirmation (X-ray) is the gold standard for verifying correct placement of a blindly inserted feeding tube before the first feeding or medication is given, since auscultation alone is unreliable and can miss tracheobronchial placement.', 'Research & Nursing Process'),
(196, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Your patient has developed a low-grade fever and states that she has felt very tired lately. You interpret these findings as indicating which stage of infection?', '["Full stage of illness", "Incubation period", "Convalescent period", "Prodromal stage"]'::jsonb, 3, 'Low-grade fever and fatigue before specific symptoms appear describe the prodromal stage of infection.', 'Research & Nursing Process'),
(197, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A test''s sensitivity is the proportion of:', '["All tests that are correct", "Positive tests that are true positives", "Patients with the disease who test positive", "Patients without the disease who test negative"]'::jsonb, 2, 'High sensitivity rules out disease when the test is negative (SnOut).', 'Research & Nursing Process'),
(198, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A study reports p = 0.03. This means that:', '["With no real effect, a result this extreme would occur 3% of the time", "The study lost 3% of its data, so the result is not valid", "3% of the patients in the study had serious side effects", "There is a 97% chance that the new treatment really works"]'::jsonb, 0, 'p < 0.05 is usually called statistically significant; it does not show clinical importance.', 'Research & Nursing Process'),
(199, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A type I error in research is:', '["Losing participants during follow-up", "Rejecting a null hypothesis that is actually true", "Accepting a null hypothesis that is false", "Using the wrong sample size"]'::jsonb, 1, 'It is a false positive; a type II error is a false negative.', 'Research & Nursing Process'),
(200, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'On a chest X-ray, the tip of an adult endotracheal tube should lie about:', '["At the level of the vocal cords", "In the right main bronchus", "Below the carina in the left bronchus", "3–5 cm above the carina"]'::jsonb, 3, 'A tube that is too deep usually enters the right main bronchus.', 'Research & Nursing Process');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
